template<class T> struct Box { template<class U> using Rebind=U; };
template<template<class> class F> struct Apply { using type=F<int>; };
template<class T> struct Base { using type=typename Apply<T::template Rebind>::type; };
template<class T> struct Owner:Base<Box<T>> {
  template<class U,class=void> struct Pick {
    static int run(int x) { return x+3; }
  };
};
template<class A> template<class B>
struct Owner<A>::Pick<B,typename B::type> {
  static int run(int x) { return x+5; }
};
struct Present { using type=void; };
int main() {
  return Owner<char>::Pick<int>::run(7)+Owner<char>::Pick<Present>::run(7)-22;
}
